// First-run developer setup: create .env.local with fresh secrets (if missing), migrate, seed.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { randomBytes } from 'node:crypto';
import { execSync } from 'node:child_process';

const ENV = '.env.local';

if (!existsSync(ENV)) {
  const lines = [
    '# Generated by `npm run setup` for local development. Never commit this file.',
    '# Leave DATABASE_URL unset to use the embedded PGlite database in .data/pglite',
    '# DATABASE_URL=postgres://user:pass@localhost:5432/zimmed',
    `BETTER_AUTH_SECRET=${randomBytes(32).toString('base64')}`,
    'BETTER_AUTH_URL=http://localhost:3000',
    '# Back up this key separately from the database: losing it makes clinical notes unreadable.',
    `FIELD_ENCRYPTION_KEYS=v1:${randomBytes(32).toString('base64')}`,
    `CRON_SECRET=${randomBytes(24).toString('hex')}`,
    'SCHEDULER=on',
    '# Mandatory TOTP for admin/doctor roles. Disabled for local demo convenience only — keep true in production.',
    'ENFORCE_2FA=false',
    '# Messaging providers (see docs/THIRD_PARTY.md). Without them messages are logged / offered as click-to-chat.',
    '# WHATSAPP_TOKEN=',
    '# WHATSAPP_PHONE_NUMBER_ID=',
    '# SMS_GATEWAY_URL=https://api.sms-gate.app/3rdparty/v1',
    '# SMS_GATEWAY_USER=',
    '# SMS_GATEWAY_PASSWORD=',
    '# SMTP_HOST=smtp-relay.brevo.com',
    '# SMTP_PORT=587',
    '# SMTP_USER=',
    '# SMTP_PASS=',
    '# SMTP_FROM="Practice Claims <claims@example.co.zw>"',
  ];
  writeFileSync(ENV, lines.join('\n') + '\n', { mode: 0o600 });
  console.log(`✔ Created ${ENV} with new secrets`);
} else {
  console.log(`• ${ENV} already exists — keeping existing secrets`);
}

// Load env for the child processes
for (const line of readFileSync(ENV, 'utf8').split('\n')) {
  const m = /^([A-Z_0-9]+)=(.*)$/.exec(line);
  if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2];
}

execSync('npx tsx --conditions=react-server scripts/migrate.ts', { stdio: 'inherit', env: process.env });
execSync('npx tsx --conditions=react-server src/server/db/seed.ts', { stdio: 'inherit', env: process.env });
